mapper.update:
UPDATE biz_guide_sheet_draft
SET sheet_id = #{sheetId},
    content_json = #{contentJson},
    revision = revision + 1,
    update_by = #{updateBy},
    update_time = #{updateTime}
WHERE owner_id = #{ownerId}
  AND client_draft_key = #{clientDraftKey}
  AND revision = #{expectedRevision}
  AND draft_status = 'D'

UPDATE biz_guide_sheet_draft
SET draft_status = 'C',
    revision = revision + 1,
    update_by = #{updateBy},
    update_time = #{completedTime},
    completed_time = #{completedTime}
WHERE owner_id = #{ownerId}
  AND client_draft_key = #{clientDraftKey}
  AND revision = #{expectedRevision}
  AND draft_status = 'D'
